.jui-all-set {
  --all-set-ink: #191414;
  --all-set-paper: #ffffff;
  --all-set-reveal: 1500ms;
  --all-set-font: "Helvetica Neue", Helvetica, Arial, sans-serif;
  position: relative;
  isolation: isolate;
  display: grid;
  align-content: center;
  justify-items: center;
  gap: clamp(28px, 6vh, 48px);
  min-height: 100%;
  width: 100%;
  padding: 48px 24px 64px;
  overflow: hidden;
  background: var(--all-set-paper);
  color: var(--all-set-ink);
  font-family: "Helvetica Neue", Helvetica, Arial, sans-serif;
}

.jui-all-set-burst {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  pointer-events: none;
}

.jui-all-set-title {
  position: relative;
  z-index: 1;
  margin: 0;
  max-width: 16ch;
  font-family: var(--all-set-font);
  font-size: clamp(36px, 6.4vw, 76px);
  font-weight: 700;
  letter-spacing: -0.03em;
  line-height: 1.05;
  text-align: center;
  text-wrap: balance;
}

.jui-all-set[data-motion="wipe"] .jui-all-set-title {
  color: transparent;
  background: linear-gradient(var(--all-set-ink), var(--all-set-ink)) 0 0 / 0 100% no-repeat;
  -webkit-background-clip: text;
  background-clip: text;
  animation: jui-all-set-reveal var(--all-set-reveal) linear both;
}

.jui-all-set-write {
  display: block;
  width: min(92vw, 760px);
  height: auto;
  overflow: visible;
  font-family: var(--all-set-font);
  font-size: 104px;
  font-weight: 700;
  letter-spacing: -0.03em;
}

.jui-all-set-stroke {
  fill: transparent;
  stroke: var(--all-set-ink);
  stroke-width: 2px;
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-dasharray: 900;
  stroke-dashoffset: 900;
  animation: jui-all-set-write 1.05s ease forwards;
}

.jui-all-set-action {
  position: relative;
  z-index: 1;
  border: 0;
  border-radius: 999px;
  padding: 16px 32px;
  background: var(--all-set-ink);
  color: var(--all-set-paper);
  font: inherit;
  font-size: 16px;
  font-weight: 700;
  letter-spacing: 0.04em;
  line-height: 1;
  text-transform: uppercase;
  cursor: pointer;
  opacity: 0;
  animation: jui-all-set-action 480ms ease both;
  animation-delay: calc(var(--all-set-reveal) + 120ms);
}

.jui-all-set-action:hover {
  transform: scale(1.04);
}

.jui-all-set-action:active {
  transform: scale(0.98);
}

.jui-all-set-action:focus-visible {
  outline: 2px solid var(--all-set-ink);
  outline-offset: 4px;
}

.jui-all-set-sr {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

@keyframes jui-all-set-reveal {
  to {
    background-size: 100% 100%;
  }
}

@keyframes jui-all-set-write {
  70% {
    fill: transparent;
  }
  to {
    stroke-dashoffset: 0;
    fill: var(--all-set-ink);
  }
}

@keyframes jui-all-set-action {
  to {
    opacity: 1;
  }
}

@media (prefers-reduced-motion: reduce) {
  .jui-all-set[data-motion="wipe"] .jui-all-set-title {
    animation: none;
    color: var(--all-set-ink);
    background: none;
  }

  .jui-all-set-stroke {
    animation: none;
    stroke-dashoffset: 0;
    fill: var(--all-set-ink);
  }

  .jui-all-set-action {
    animation: none;
    opacity: 1;
  }
}

"use client";

import {
  useEffect,
  useRef,
  useState,
  type ComponentProps,
  type CSSProperties,
} from "react";
import confetti from "canvas-confetti";
import { useReducedMotion } from "motion/react";
import { cn } from "@/lib/utils";
import "./all-set.css";

export const allSetFonts = [
  {
    id: "sans",
    label: "黑体",
    family: '"Helvetica Neue", Helvetica, Arial, sans-serif',
  },
  {
    id: "serif",
    label: "衬线",
    family: 'Georgia, "Times New Roman", "Songti SC", serif',
  },
  {
    id: "mono",
    label: "等宽",
    family: '"Courier New", Courier, monospace',
  },
  {
    id: "script",
    label: "手写",
    family: '"Segoe Script", "Brush Script MT", "Comic Sans MS", KaiTi, STKaiti, cursive',
  },
] as const;

export type AllSetFont = (typeof allSetFonts)[number]["id"];
export type AllSetMotion = "wipe" | "handwriting";

export type AllSetProps = Omit<ComponentProps<"section">, "title"> & {
  title?: string;
  actionLabel?: string;
  font?: AllSetFont;
  motion?: AllSetMotion;
  replayKey?: string | number;
  onAction?: () => void;
};

const palette = ["#1ed760", "#1db954", "#191414", "#b3b3b3", "#ffffff", "#535353"];

export function AllSet({
  title = "You're all set",
  actionLabel = "Open JungUI",
  font = "sans",
  motion = "wipe",
  replayKey,
  onAction,
  className,
  ...props
}: AllSetProps) {
  return (
    <AllSetRun
      key={replayKey}
      title={title}
      actionLabel={actionLabel}
      font={font}
      motion={motion}
      onAction={onAction}
      className={className}
      {...props}
    />
  );
}

function AllSetRun({
  title = "You're all set",
  actionLabel = "Open JungUI",
  font = "sans",
  motion = "wipe",
  onAction,
  className,
  style,
  ...props
}: AllSetProps) {
  const reduced = useReducedMotion();
  const stage = useRef<HTMLElement>(null);
  const burst = useRef<ReturnType<typeof confetti.create> | null>(null);
  const timers = useRef<number[]>([]);
  const [ready, setReady] = useState(false);
  const letters = [...title];
  const cjk = /[^\u0000-\u00ff]/.test(title);
  const family = allSetFonts.find((item) => item.id === font)?.family ?? allSetFonts[0].family;
  const step = cjk ? 340 : 200;
  const draw = cjk ? 1100 : 820;
  const reveal = motion === "wipe" ? 1500 : Math.max(0, letters.length - 1) * step + draw;
  const viewWidth = Math.ceil(letters.length * (cjk ? 118 : 58) + 48);

  useEffect(() => {
    const canvas = stage.current?.querySelector("canvas");
    if (!(canvas instanceof HTMLCanvasElement)) return;
    const fit = () => {
      const parent = canvas.parentElement;
      if (!parent) return;
      const width = parent.clientWidth;
      const height = parent.clientHeight;
      const ratio = window.devicePixelRatio || 1;
      canvas.width = Math.max(1, Math.floor(width * ratio));
      canvas.height = Math.max(1, Math.floor(height * ratio));
    };
    fit();
    const observer = new ResizeObserver(fit);
    observer.observe(canvas.parentElement!);
    const shoot = confetti.create(canvas, { resize: false, useWorker: false });
    burst.current = shoot;
    const clear = () => {
      timers.current.forEach((id) => window.clearTimeout(id));
      timers.current = [];
      shoot.reset();
    };
    if (reduced) {
      return () => {
        clear();
        observer.disconnect();
      };
    }
    const fire = (options: confetti.Options) => {
      void shoot({
        colors: palette,
        disableForReducedMotion: true,
        ...options,
      });
    };
    const cheer = () => {
      fire({
        particleCount: 90,
        spread: 70,
        startVelocity: 48,
        origin: { x: 0.5, y: 0.62 },
        scalar: 0.9,
      });
      fire({
        particleCount: 36,
        angle: 60,
        spread: 55,
        startVelocity: 55,
        origin: { x: 0, y: 0.55 },
      });
      fire({
        particleCount: 36,
        angle: 120,
        spread: 55,
        startVelocity: 55,
        origin: { x: 1, y: 0.55 },
      });
    };
    cheer();
    timers.current.push(window.setTimeout(cheer, 280));
    return () => {
      clear();
      observer.disconnect();
    };
  }, [reduced]);

  useEffect(() => {
    const id = window.setTimeout(() => setReady(true), reduced ? 0 : reveal);
    return () => window.clearTimeout(id);
  }, [reduced, reveal]);

  return (
    <section
      {...props}
      ref={stage}
      data-slot="all-set"
      data-motion={motion}
      data-ready={ready || undefined}
      className={cn("jui-all-set", className)}
      style={
        {
          ...style,
          "--all-set-font": family,
          "--all-set-reveal": `${reveal}ms`,
        } as CSSProperties
      }
    >
      <canvas className="jui-all-set-burst" aria-hidden="true" />
      <h1 className="jui-all-set-title">
        {motion === "handwriting" ? (
          <>
            <span className="jui-all-set-sr">{title}</span>
            <svg
              className="jui-all-set-write"
              viewBox={`0 0 ${viewWidth} 168`}
              role="img"
              aria-hidden="true"
            >
              <text x="50%" y="112" textAnchor="middle">
                {letters.map((letter, index) => (
                  <tspan
                    key={`${letter}-${index}`}
                    className="jui-all-set-stroke"
                    style={{ animationDelay: `${index * step}ms` }}
                  >
                    {letter === " " ? "\u00a0" : letter}
                  </tspan>
                ))}
              </text>
            </svg>
          </>
        ) : (
          title
        )}
      </h1>
      <button
        type="button"
        className="jui-all-set-action"
        onClick={() => {
          burst.current?.reset();
          onAction?.();
        }}
      >
        {actionLabel}
      </button>
    </section>
  );
}

import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}
